 * Hooks
 * -----------------------------------------------------------------------------------------------*/

/**
 * The live aim inside `<PieMenuContent>`. It re-renders on every pointer move.
 * For styles, prefer the `--pie-aim-*` CSS variables: they update without a render.
 */
export function usePieMenuAim() {
  return useAimStore(useContentContext("usePieMenuAim").aimStore)
}

/**
 * Pure math for pie menus. Angles are in radians, measured clockwise from
 * 12 o'clock, so 0 is "up" and PI / 2 is "right". Screen y grows downward.
 */

export const TAU = Math.PI * 2

export interface Point {
  x: number
  y: number
}

export interface Size {
  width: number
  height: number
}

export interface ItemLayout {
  index: number
  angle: number
  /** Offset of the anchor point from the menu center, in px. */
  x: number
  y: number
  sin: number
  cos: number
}

export function degToRad(degrees: number) {
  return (degrees * Math.PI) / 180
}

export function radToDeg(radians: number) {
  return (radians * 180) / Math.PI
}

export function normalizeAngle(angle: number) {
  return ((angle % TAU) + TAU) % TAU
}

/** Angle of a vector in screen space. */
export function vectorAngle(dx: number, dy: number) {
  return normalizeAngle(Math.atan2(dx, -dy))
}

/** Smallest distance between two angles, in the range [0, PI]. */
export function angularDistance(a: number, b: number) {
  const diff = Math.abs(normalizeAngle(a) - normalizeAngle(b))
  return Math.min(diff, TAU - diff)
}

export function itemAngle(index: number, count: number, startAngle = 0) {
  return normalizeAngle(startAngle + (index * TAU) / count)
}

export function layoutItems(count: number, radius: number, startAngle = 0): ItemLayout[] {
  return Array.from({ length: count }, (_, index) => {
    const angle = itemAngle(index, count, startAngle)
    const sin = Math.sin(angle)
    const cos = Math.cos(angle)
    return { index, angle, sin, cos, x: sin * radius, y: -cos * radius }
  })
}

/** Index of the wedge that contains the angle. Each wedge is centered on its item. */
export function wedgeIndex(angle: number, count: number, startAngle = 0) {
  if (count === 0) return -1
  const slice = TAU / count
  return Math.round(normalizeAngle(angle - startAngle) / slice) % count
}

/** Index of the enabled item closest to the angle, or -1 when no item is enabled. */
export function nearestIndex(angle: number, angles: readonly number[], enabled: readonly boolean[]) {
  let best = -1
  let bestDistance = Infinity
  angles.forEach((itemAngle, index) => {
    if (!enabled[index]) return
    const distance = angularDistance(angle, itemAngle)
    if (distance < bestDistance - 1e-9) {
      best = index
      bestDistance = distance
    }
  })
  return best
}

/** Next enabled index when walking the ring. Returns -1 when no item is enabled. */
export function stepIndex(from: number, step: 1 | -1, enabled: readonly boolean[]) {
  const count = enabled.length
  for (let offset = 1; offset <= count; offset++) {
    const index = (((from + step * offset) % count) + count) % count
    if (enabled[index]) return index
  }
  return -1
}

/**
 * Where an item box sits relative to its anchor point. Boxes grow away from the
 * center: a right-side label starts at the anchor, a top label ends at it.
 * The result is a fraction of the box size, in the range [-1, 0].
 */
export function anchorOffset(sin: number, cos: number) {
  return { x: -0.5 + 0.5 * sin, y: -0.5 - 0.5 * cos }
}

/** CSS `translate` value that puts an item box at its anchor point. */
export function itemTranslate(layout: ItemLayout) {
  const offset = anchorOffset(layout.sin, layout.cos)
  const px = (value: number) => `${round(value)}px`
  const pct = (value: number) => `${round(value * 100)}%`
  return `calc(${px(layout.x)} + ${pct(offset.x)}) calc(${px(layout.y)} + ${pct(offset.y)})`
}

export interface Extents {
  left: number
  right: number
  top: number
  bottom: number
}

/** Bounding box of all item boxes and a centered box, relative to the menu center. */
export function menuExtents(layouts: readonly ItemLayout[], sizes: readonly Size[], centerSize?: Size): Extents {
  const extents: Extents = { left: 0, right: 0, top: 0, bottom: 0 }
  const include = (left: number, top: number, size: Size) => {
    extents.left = Math.min(extents.left, left)
    extents.top = Math.min(extents.top, top)
    extents.right = Math.max(extents.right, left + size.width)
    extents.bottom = Math.max(extents.bottom, top + size.height)
  }
  layouts.forEach((layout, index) => {
    const size = sizes[index]
    if (!size) return
    const offset = anchorOffset(layout.sin, layout.cos)
    include(layout.x + offset.x * size.width, layout.y + offset.y * size.height, size)
  })
  if (centerSize) include(-centerSize.width / 2, -centerSize.height / 2, centerSize)
  return extents
}

/** Scale that makes the menu fit inside the viewport, never above 1 and never below `min`. */
export function fitScale(extents: Extents, viewport: Size, padding = 8, min = 0.5) {
  const width = extents.right - extents.left
  const height = extents.bottom - extents.top
  const scale = Math.min(1, (viewport.width - padding * 2) / width, (viewport.height - padding * 2) / height)
  return Math.max(min, Number.isFinite(scale) ? scale : 1)
}

export function scaleExtents(extents: Extents, scale: number): Extents {
  return {
    left: extents.left * scale,
    right: extents.right * scale,
    top: extents.top * scale,
    bottom: extents.bottom * scale,
  }
}

/** Moves the center so the whole menu stays inside the viewport. */
export function clampCenter(point: Point, extents: Extents, viewport: Size, padding = 8): Point {
  const clampAxis = (value: number, min: number, max: number, size: number) =>
    min > max ? size / 2 : Math.min(Math.max(value, min), max)
  return {
    x: clampAxis(point.x, padding - extents.left, viewport.width - padding - extents.right, viewport.width),
    y: clampAxis(point.y, padding - extents.top, viewport.height - padding - extents.bottom, viewport.height),
  }
}

/** Rotation target in degrees that turns the shortest way from the current value. */
export function shortestRotation(fromDegrees: number, toDegrees: number) {
  const delta = ((((toDegrees - fromDegrees) % 360) + 540) % 360) - 180
  return fromDegrees + delta
}

function round(value: number) {
  return Math.round(value * 100) / 100
}

import { useSyncExternalStore } from "react"

import { radToDeg, vectorAngle } from "./geometry"

/**
 * Where the user "aims" inside an open pie menu: the pointer direction, or the
 * direction of the highlighted item when the user drives the menu by keyboard.
 * `x` and `y` are in the range [-1, 1], relative to the menu radius.
 */
export interface Aim {
  x: number
  y: number
  /** Degrees, clockwise from 12 o'clock. */
  angle: number
  /** 0 at the center, 1 at the item ring or farther. */
  distance: number
}

export const IDLE_AIM: Aim = { x: 0, y: 0, angle: 0, distance: 0 }

export function aimFromVector(dx: number, dy: number, radius: number): Aim {
  const length = Math.hypot(dx, dy)
  if (length === 0) return IDLE_AIM
  const distance = Math.min(length / radius, 1)
  return {
    x: (dx / length) * distance,
    y: (dy / length) * distance,
    angle: radToDeg(vectorAngle(dx, dy)),
    distance,
  }
}

type Listener = () => void

/**
 * A tiny external store. Pointer moves arrive at display rate, so the menu
 * writes them here and to CSS variables instead of into React state.
 */
export function createAimStore(onChange: (aim: Aim) => void) {
  let aim = IDLE_AIM
  const listeners = new Set<Listener>()
  return {
    get: () => aim,
    set(next: Aim) {
      if (next.x === aim.x && next.y === aim.y) return
      aim = next
      onChange(aim)
      listeners.forEach((listener) => listener())
    },
    subscribe(listener: Listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
  }
}

export type AimStore = ReturnType<typeof createAimStore>

export function useAimStore(store: AimStore | null) {
  return useSyncExternalStore(
    store?.subscribe ?? noopSubscribe,
    store?.get ?? getIdle,
    getIdle,
  )
}

/** CSS custom properties that mirror the aim, for styles that follow the pointer. */
export function aimStyle(aim: Aim) {
  return {
    "--pie-aim-x": round(aim.x),
    "--pie-aim-y": round(aim.y),
    "--pie-aim-angle": `${round(aim.angle)}deg`,
    "--pie-aim-distance": round(aim.distance),
  }
}

const noopSubscribe = () => () => {}
const getIdle = () => IDLE_AIM

function round(value: number) {
  return String(Math.round(value * 1000) / 1000)
}

import { useCallback, useLayoutEffect, useRef, useState, type Ref } from "react"

export function useLatest<T>(value: T) {
  const ref = useRef(value)
  useLayoutEffect(() => {
    ref.current = value
  })
  return ref
}

export function useControllableState<T>(options: {
  value: T | undefined
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [uncontrolled, setUncontrolled] = useState(options.defaultValue)
  const isControlled = options.value !== undefined
  const value = isControlled ? (options.value as T) : uncontrolled
  const onChange = useLatest(options.onChange)

  const setValue = useCallback(
    (next: T) => {
      if (!isControlled) setUncontrolled(next)
      if (!Object.is(next, value)) onChange.current?.(next)
    },
    [isControlled, value, onChange],
  )

  return [value, setValue] as const
}

export function composeRefs<T>(...refs: Array<Ref<T> | undefined>) {
  return (node: T | null) => {
    const cleanups = refs.map((ref) => {
      if (typeof ref === "function") return ref(node)
      if (ref) ref.current = node
      return undefined
    })
    return () => {
      cleanups.forEach((cleanup, index) => {
        const ref = refs[index]
        if (typeof cleanup === "function") cleanup()
        else if (typeof ref === "function") ref(null)
        else if (ref) ref.current = null
      })
    }
  }
}

/** Calls the user handler first. The internal handler runs unless the user prevented it. */
export function composeHandlers<E extends { defaultPrevented: boolean }>(
  userHandler: ((event: E) => void) | undefined,
  ownHandler: (event: E) => void,
) {
  return (event: E) => {
    userHandler?.(event)
    if (!event.defaultPrevented) ownHandler(event)
  }
}

import { useEffect, useLayoutEffect, useState, type RefObject } from "react"

/**
 * - `starting`: first frame after mount. Styles show the enter start state.
 * - `entering`: enter transitions run. Use it for enter-only effects, such as a stagger.
 * - `open`: idle.
 * - `ending`: exit transitions run. The element unmounts when they finish.
 */
export type PresenceStatus = "starting" | "entering" | "open" | "ending"

/**
 * Keeps an element mounted while its CSS transitions finish, in the style of
 * Base UI's `data-starting-style` and `data-ending-style`. It waits on the Web
 * Animations API, so it works with transitions and keyframes and needs no timers.
 */
export function usePresence(present: boolean, ref: RefObject<HTMLElement | null>) {
  const [mounted, setMounted] = useState(present)
  const [status, setStatus] = useState<PresenceStatus>(present ? "open" : "ending")

  useLayoutEffect(() => {
    if (present) {
      setMounted(true)
      setStatus("starting")
    } else {
      setStatus((current) => (current === "starting" ? current : "ending"))
    }
  }, [present])

  useEffect(() => {
    if (!mounted) return
    let cancelled = false
    let frame = 0

    if (status === "starting") {
      // Two frames: the browser must paint the start state before it can transition from it.
      frame = requestAnimationFrame(() => {
        frame = requestAnimationFrame(() => setStatus(present ? "entering" : "ending"))
      })
    } else if (status === "entering" || status === "ending") {
      frame = requestAnimationFrame(() => {
        waitForAnimations(ref.current).then(() => {
          if (cancelled) return
          if (status === "entering") setStatus("open")
          else setMounted(false)
        })
      })
    }

    return () => {
      cancelled = true
      cancelAnimationFrame(frame)
    }
  }, [mounted, status, present, ref])

  return { mounted, status }
}

function waitForAnimations(element: HTMLElement | null) {
  if (!element || typeof element.getAnimations !== "function") return Promise.resolve()
  // Skip endless animations, such as a spinner inside the element. They never finish.
  const animations = element
    .getAnimations({ subtree: true })
    .filter((animation) => animation.effect?.getComputedTiming().endTime !== Infinity)
  return Promise.allSettled(animations.map((animation) => animation.finished))
}
